export type Result<T> = { ok: true; data: T } | { ok: false; error: string };
export type Produk = { id: string; name: string; price: number; stock: number };

function isProduk(x: unknown): x is Produk {
  return (
    typeof x === "object" && x !== null &&
    "id" in x && typeof x.id === "string" &&
    "name" in x && typeof x.name === "string" &&
    "price" in x && typeof x.price === "number" &&
    "stock" in x && typeof x.stock === "number"
  );
}
export async function ambilProduk(id: string): Promise<Result<Produk>> {
  try {
    const res = await fetch("https://api.toko.contoh/products/" + id);
    if (!res.ok) return { ok: false, error: "HTTP " + res.status };
    const data: unknown = await res.json();
    return isProduk(data) ? { ok: true, data } : { ok: false, error: "Data tidak valid" };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Jaringan gagal" };
  }
}
// === main.ts ===
import { ambilProduk } from "./api";

for (const id of ["P01", "P02", "P99"]) {
  const h = await ambilProduk(id);
  if (!h.ok) console.log(id, "gagal:", h.error);
  else console.log(id, h.data.name, h.data.stock > 0 ? "tersedia" : "habis");
}

