type Result<T> = { ok: true; data: T } | { ok: false; error: string };
async function ambilNama(id: string): Promise<Result<string>> {
  const res = await fetch("https://api.toko.contoh/products/" + id);
  if (!res.ok) return { ok: false, error: "HTTP " + res.status };
  const d: unknown = await res.json();
  if (typeof d === "object" && d !== null && "name" in d && typeof d.name === "string") return { ok: true, data: d.name };
  return { ok: false, error: "format" };
}
async function ambilBanyak(ids: string[]): Promise<string[]> {
  const hasil = await Promise.all(ids.map(ambilNama));
  return hasil.flatMap((h) => (h.ok ? [h.data] : []));
}
console.log((await ambilBanyak(["P01", "P99", "P03"])).join(", "));
